items=[]
def short(k,word,stem,point,groups,ex,diff=2):
 i=len(items)+1;items.append({'id':f'{sub}-i{i:02d}','kcs':[k],'kind':'short','difficulty':diff,'command_word':word,'source':{'type':'generated'},'stem':stem,'marks':1,'rubric':[{'point':point,'keywords':groups}],'explanation':ex,'hints':['Recall the relevant position or trend.','Use the given observation to narrow the possibilities.','State the chemical link before naming the result.']})
def mcq(k,word,stem,opts,ans,ex,dist=None,diff=3):
 i=len(items)+1;items.append({'id':f'{sub}-i{i:02d}','kcs':[k],'kind':'mcq','difficulty':diff,'command_word':word,'source':{'type':'generated'},'stem':stem,'marks':1,'options':dict(zip('ABCD',opts)),'answer':ans,'distractors':dist or {},'shuffle':True,'explanation':ex,'hints':['Find the relevant group or period first.','Compare the options against every clue.','Eliminate any option that conflicts with a stated trend.']})
short(k1,'Describe','Describe how the tendency of Group 2 metals to react with water changes down the group.','Reactivity with water increases down Group 2.',[['increas','faster','more reactive']], 'Down Group 2, the metals generally react more readily with water.')
short(k1,'Explain','Explain why a Group 2 metal below barium is predicted to have a lower second ionisation energy.','Greater shielding and distance weaken nuclear attraction for the second electron. ',[['shield','screen'],['distance','farther','further']], 'The second electron is farther from the nucleus and more shielded.')
mcq(k1,'Predict','A new element lies below barium in Group 2. Which property is most likely?',['A higher second ionisation energy than barium','A less soluble hydroxide than barium hydroxide','A more thermally stable carbonate than barium carbonate','A slower reaction with water than barium'],'C','Thermal stability of Group 2 carbonates generally increases down the group; the other options reverse established trends.',{'A':'m1','B':'m1','D':'m1'},4)
short(k1,'Predict','Predict whether the hydroxide of an element below calcium in Group 2 is more or less soluble in water than calcium hydroxide.','More soluble.',[['more soluble','increases']], 'Group 2 hydroxide solubility generally increases down the group.')
short(k1,'Predict','Predict the relative first ionisation energies of two elements in the same group, with X above Y.','X generally has the higher first ionisation energy.',[['higher','greater'],['X']], 'Moving down a group increases shielding and atomic radius, so first ionisation energy generally falls.')
short(k1,'Explain','Explain how a common outer-electron arrangement helps predict properties of elements in one group.','Same outer electron count gives similar chemical properties.',[['same','similar'],['outer','valence']], 'Members of a group have the same number of outer-shell electrons and often similar chemistry.')
short(k2,'Deduce','An unknown atom has three occupied electron shells and one outer electron. Deduce its period and group.','Period 3, Group 1.',[['period 3'],['group 1']], 'Three occupied shells place it in Period 3; one outer electron places it in Group 1.')
short(k2,'Deduce','A Period 3 metal forms a white hydroxide precipitate that dissolves in excess aqueous sodium hydroxide. Deduce the metal.','Aluminium.',[['aluminium','aluminum']], 'Aluminium hydroxide is amphoteric and dissolves in excess alkali.')
short(k2,'Explain','Explain why a white precipitate with aqueous sodium hydroxide does not by itself distinguish magnesium from aluminium ions.','Both ions form white hydroxide precipitates.',[['both','magnesium and aluminium'],['white','precipitate']], 'Both hydroxides are white; excess alkali distinguishes them.')
mcq(k2,'Deduce','An element requires strong heating to react with oxygen and forms a covalent chloride. Which Period 3 element fits?',['Sodium','Magnesium','Silicon','Argon'],'C','Silicon reacts on strong heating and forms covalent silicon tetrachloride.',{'A':'m4','B':'m4','D':'m3'},4)
short(k2,'Deduce','An unknown element is in Period 3 and has the second largest atomic radius in that period. Deduce its identity.','Magnesium.',[['magnesium']], 'Atomic radius generally decreases across Period 3, placing magnesium second after sodium.')
short(k2,'Explain','Explain why both physical and chemical properties should be checked before identifying an unknown element.','Different elements can share individual properties, so all clues must fit one identity.',[['all','every','both'],['clue','property','observation']], 'A single property can be shared; agreement across independent observations makes the deduction stronger.')
# Keep only complete, distinct original bank entries.
